package com.anthony6996.hardcorecompass.command;
import com.anthony6996.hardcorecompass.HardcoreCompassPlugin;import com.anthony6996.hardcorecompass.config.ConfigManager;import com.anthony6996.hardcorecompass.manager.CompassManager;import com.anthony6996.hardcorecompass.manager.LivesManager;import org.bukkit.Bukkit;import org.bukkit.command.*;import org.bukkit.entity.Player;import org.bukkit.inventory.ItemStack;import java.util.*;
public final class CompassCommand implements CommandExecutor,TabCompleter{private final HardcoreCompassPlugin plugin;private final LivesManager lives;private final ConfigManager config;private final CompassManager compasses;public CompassCommand(HardcoreCompassPlugin p,LivesManager l,ConfigManager c,CompassManager m){plugin=p;lives=l;config=c;compasses=m;}private String msg(CommandSender s,String k){return config.localized(s instanceof Player p?config.language(p):config.defaultLanguage(),k);}private boolean admin(CommandSender s){return s.hasPermission("hardcorecompass.admin");}
@Override public boolean onCommand(CommandSender s,Command cmd,String label,String[] a){if(a.length==0||a[0].equalsIgnoreCase("help")){s.sendMessage(msg(s,admin(s)?"help-admin":"help-player"));return true;}String sub=a[0].toLowerCase(Locale.ROOT);if(sub.equals("reload")&&admin(s)){plugin.reloadPluginConfig();s.sendMessage(msg(s,"reloaded"));return true;}if(sub.equals("radius")){if(!admin(s)){s.sendMessage(msg(s,"no-permission"));return true;}if(a.length!=3){s.sendMessage(msg(s,"radius-usage"));return true;}try{int min=Integer.parseInt(a[1]),max=Integer.parseInt(a[2]);if(min<0||max<min)throw new NumberFormatException();config.setRadius(min,max);s.sendMessage(msg(s,"radius-set").replace("{min}",String.valueOf(min)).replace("{max}",String.valueOf(max)));}catch(NumberFormatException ex){s.sendMessage(msg(s,"radius-usage"));}return true;}if(sub.equals("lang")){if(a.length==1){if(!(s instanceof Player p)){s.sendMessage(msg(s,"lang-usage"));return true;}String lang=plugin.getPlayerData().getLanguage(p.getUniqueId());s.sendMessage(lang==null?msg(s,"lang-current-default"):config.getMessage(p,"lang-current"));return true;}if(a.length==2&&s instanceof Player p){String lang=a[1].toLowerCase(Locale.ROOT);if(!lang.equals("es")&&!lang.equals("en")){s.sendMessage(msg(s,"lang-usage"));return true;}plugin.getPlayerData().setLanguage(p.getUniqueId(),lang);plugin.getPlayerData().save();s.sendMessage(msg(s,"lang-set"));return true;}s.sendMessage(msg(s,"lang-usage"));return true;}if(sub.equals("give")){if(!admin(s)){s.sendMessage(msg(s,"no-permission"));return true;}if(a.length<2||a.length>3){s.sendMessage(msg(s,"give-usage"));return true;}Player t=Bukkit.getPlayerExact(a[1]);if(t==null){s.sendMessage(msg(s,"player-not-found"));return true;}String kind=a.length==3?a[2].toLowerCase(Locale.ROOT):"all";if(!Set.of("compass","lodestone","all").contains(kind)){s.sendMessage(msg(s,"give-usage"));return true;}if(kind.equals("compass")||kind.equals("all"))give(t,compasses.createCompass(null,t));if(kind.equals("lodestone")||kind.equals("all"))give(t,compasses.createLodestone(t));s.sendMessage(msg(s,kind.equals("all")?"give-success-all":"give-success").replace("{player}",t.getName()).replace("{item}",kind));return true;}if(sub.equals("info")){if(!admin(s)&&a.length>1){s.sendMessage(msg(s,"no-permission"));return true;}Player t=a.length>1?Bukkit.getPlayerExact(a[1]):(s instanceof Player p?p:null);if(t==null){s.sendMessage(msg(s,"player-not-found"));return true;}s.sendMessage(msg(s,"info").replace("{player}",t.getName()).replace("{lives}",""+lives.lives(t.getUniqueId())).replace("{deaths}",""+lives.deaths(t.getUniqueId())).replace("{compass}",""+lives.hasPreservedCompass(t.getUniqueId())));return true;}if(sub.equals("reset")&&admin(s)&&a.length==2){Player t=Bukkit.getPlayerExact(a[1]);if(t==null){s.sendMessage(msg(s,"player-not-found"));return true;}lives.reset(t.getUniqueId());s.sendMessage(msg(s,"reset").replace("{player}",t.getName()));return true;}s.sendMessage(msg(s,admin(s)?"help-admin":"help-player"));return true;}
private void give(Player p,ItemStack i){Map<Integer,ItemStack> extra=p.getInventory().addItem(i);extra.values().forEach(x->p.getWorld().dropItemNaturally(p.getLocation(),x));}@Override public List<String> onTabComplete(CommandSender s,Command c,String a,String[] args){if(args.length==1)return filter(admin(s)?List.of("help","lang","info","give","reset","radius","reload"):List.of("help","lang"),args[0]);if(args.length==2&&args[0].equalsIgnoreCase("give"))return filter(Bukkit.getOnlinePlayers().stream().map(Player::getName).toList(),args[1]);if(args.length==3&&args[0].equalsIgnoreCase("give"))return filter(List.of("compass","lodestone","all"),args[2]);if(args.length==2&&args[0].equalsIgnoreCase("lang"))return filter(List.of("en","es"),args[1]);return List.of();}private List<String> filter(List<String> list,String p){return list.stream().filter(x->x.regionMatches(true,0,p,0,p.length())).toList();}}
